import{_ as e}from"./chunks/maintenance-pwr.pc.ko.BZ22xKJ9.js";import{_ as o,o as t,c,a5 as a}from"./chunks/framework.BjM_ivYE.js";const r="/RBQ/images/app/maintenance-vision.pc.ko.png",i="/RBQ/images/app/maintenance-ini.pc.ko.png",_=JSON.parse('{"title":"정비","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/maintenance.md","filePath":"ko/manual/gui/maintenance.md","lastUpdated":1790655143000}'),n={name:"ko/manual/gui/maintenance.md"};function l(p,d,s,h,m,g){return t(),c("div",null,[...d[0]||(d[0]=[a('<h1 id="정비" tabindex="-1">정비 <a class="header-anchor" href="#정비" aria-label="Permalink to &quot;정비&quot;">​</a></h1><p>허브의 <code>정비</code> 타일로 엽니다. 타일은 로봇이 연결돼 있을 때 눌립니다. 섹션은 <code>전원 / 시스템</code>, <code>비전</code>, <code>설정 파일</code>, 그리고 팔이 있는 로봇에서만 보이는 <code>팔</code>입니다.</p><p><strong>이 화면은 통째로 <a href="/RBQ/ko/manual/gui/developer-mode.html">개발자 모드</a> 전용입니다.</strong> 개발자 모드가 아니면 허브에 <code>정비</code> 타일이 나오지 않고, 경로로 직접 들어와도 제어 홈으로 되돌아갑니다. 여기의 조작은 연결을 끊거나 로봇을 주저앉히거나 데몬 기동 방식을 바꿉니다 — 누르기 전에 각 경고를 읽으세요.</p><h2 id="전원-시스템" tabindex="-1">전원 / 시스템 <a class="header-anchor" href="#전원-시스템" aria-label="Permalink to &quot;전원 / 시스템&quot;">​</a></h2><p><img src="'+e+'" alt="전원 / 시스템 섹션"></p><p>설정에서 일부러 뺀 레일까지 모든 PDU 레일이 여기 있습니다. 토글은 로봇이 보고한 실제 레일 상태를 표시하며, 상태를 받기 전에는 비활성화됩니다.</p><p><strong>12 V 토글</strong>(한 번 탭): <code>스피커 앰프 (12V)</code>, <code>LiDAR (12V)</code>, <code>CCTV (12V)</code>, <code>열화상 (12V)</code>, <code>IR LED (12V)</code>.</p><p><strong>끄면 연결이 끊기는 레일</strong>(2단계 확인 <code>정말 끌까요?</code> → <code>끄기</code>. 확인 창에 <code>하루 동안 묻지 않음</code> 체크박스가 있으며, 체크하면 이 화면에서만 해당 레일을 24시간 동안 확인 없이 전환합니다. 로봇 설정 → 전원 제어는 항상 확인합니다):</p><table tabindex="0"><thead><tr><th>레일</th><th>끄면</th></tr></thead><tbody><tr><td><code>카메라 (5V)</code></td><td>영상이 끊깁니다.</td></tr><tr><td><code>오디오·USB 허브 (5V)</code></td><td>오디오 장치가 사라집니다.</td></tr><tr><td><code>Vision PC (12V)</code></td><td>카메라·오디오와 이 화면의 텔레메트리 일부가 끊깁니다.</td></tr><tr><td><code>통신 (12V)</code></td><td>이 앱과 로봇의 연결 자체가 끊깁니다.</td></tr></tbody></table><p><strong>48 V 구동 레일</strong>(2단계, 현재 전압 표시):</p><table tabindex="0"><thead><tr><th>레일</th><th>비고</th></tr></thead><tbody><tr><td><code>LEGS (48V 구동)</code></td><td>다리 모터 전원. 로봇이 서 있지 않을 때(앉음·제어 꺼짐·낙상)만 끌 수 있으며, 그 외에는 행이 차단됩니다.</td></tr><tr><td><code>ARM · ADDON (48V)</code></td><td>팔과 애드온 전원 — 포트 하나를 함께 씁니다. 팔이 정지 상태인지 먼저 확인하세요.</td></tr><tr><td><code>EXTERN (48V)</code></td><td>외부 확장 포트 전원.</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><code>LEGS (48V 구동)</code>을 끄면 로봇이 주저앉습니다. <code>시스템 재부팅</code> — <code>재부팅</code> → <code>로봇 PC를 재부팅할까요?</code> → <code>재부팅</code> — 은 로봇 PC를 재시작합니다. 그동안 로봇은 모터 전원을 잃고 앱 연결이 끊깁니다. 두 조작 모두 로봇을 바닥에 앉힌 뒤에 하세요. 재부팅 확인 창에도 <code>하루 동안 묻지 않음</code> 체크박스가 있습니다.</p></div><p>48 V 레일 아래에는 <a href="/RBQ/ko/manual/gui/settings.html#calibration">로봇 설정 → 캘리브레이션</a>에서 설명한 <code>가속도계 보정 (ACC)</code>과 <code>IMU 롤/피치 영점</code> 행이 한 번 더 있으며, 동작은 동일합니다.</p><h2 id="비전" tabindex="-1">비전 <a class="header-anchor" href="#비전" aria-label="Permalink to &quot;비전&quot;">​</a></h2><p><img src="'+r+'" alt="비전 섹션"></p><table tabindex="0"><thead><tr><th>행</th><th>동작</th></tr></thead><tbody><tr><td><code>야간 모드 (Night Vision)</code></td><td>IR-cut 필터를 전환합니다. CCTV IR-cut과 IR LED가 연동되며, 주간으로 바꾸면 IR LED가 꺼집니다.</td></tr><tr><td><code>IR 프로젝터</code></td><td>뎁스 카메라 도트 프로젝터. 야간 모드와 독립이며, 프로젝터가 있는 로봇에서만 표시됩니다.</td></tr><tr><td><code>스텔스 모드 (LED·부저 OFF)</code></td><td>LED와 부저를 동시에 끕니다.</td></tr><tr><td><code>GUIDE 오버레이</code></td><td>영상 위에 가이드(Aruco 십자선·박스)를 그립니다.</td></tr><tr><td><code>FACE DETECT</code></td><td>영상 위에 얼굴 박스를 그립니다.</td></tr><tr><td><code>Dock Scan (도킹 마커)</code></td><td>로봇이 카메라 영상에서 도킹 마커를 검출할지 정합니다. 마커가 잡히면 오버레이와 <code>도킹 시작</code> 버튼이 나옵니다. 도킹이 진행되는 동안에는 이 설정과 상관없이 마커를 그립니다.</td></tr><tr><td><code>영상 해상도 (SQHD)</code></td><td>WebRTC 인코더 출력 해상도: HD 720p / SQHD 540 / <code>절약 360</code> — 링크가 약하면 낮추세요.</td></tr></tbody></table><p><code>IR 프로젝터</code>와 <code>영상 해상도 (SQHD)</code>는 로봇이 알려주는 실제 상태를 표시합니다. 나머지 토글은 이 로봇에 마지막으로 보낸 값입니다 — 앱이 로봇별로 기억하므로 페이지를 옮기거나 앱을 다시 켜도 유지되지만, 로봇이 재시작하면 달라질 수 있습니다(섹션 맨 아래 안내 문구에 같은 내용이 있습니다).</p><p><code>Heightmap 설정</code> — <code>Stairs</code>는 계단 지형 인식을 켜고, <code>Edge</code>는 단차(모서리) 감지를 켭니다. <code>Edge</code>는 <code>Stairs</code>가 켜져 있을 때만 쓸 수 있습니다.</p><p><code>데몬 제어</code> — <code>VISION RESET</code> → <code>리셋</code>은 Handler가 HAL을 재시작해 카메라 파이프라인을 깨끗하게 재시작합니다. 영상이 수 초 끊기며, 버튼은 <code>리셋 중…</code>으로 바뀌어 약 8초 동안 비활성화됩니다.</p><p><code>Vision Programs</code>에서는 비전 데몬(<code>Vision</code>, <code>HAL</code>, <code>Streamer</code>, <code>Handeye</code>, <code>Heightmap</code>, <code>Cctv</code>, <code>Ptz</code>, <code>Thermal</code>)을 하나씩 수동으로 시작·정지할 수 있습니다. 켜짐/꺼짐 표시는 로봇이 보고한 프로그램 상태를 따르며, 상태를 보고하지 않는 구형 데몬에서만 마지막으로 보낸 명령 기준으로 표시합니다.</p><h2 id="설정-파일" tabindex="-1">설정 파일 <a class="header-anchor" href="#설정-파일" aria-label="Permalink to &quot;설정 파일&quot;">​</a></h2><p><img src="'+i+'" alt="설정 파일 섹션"></p><p>INI 에디터는 로봇 데몬의 설정 파일을 직접 편집합니다. 대상 선택기로 <code>Motion.ini</code>, <code>HAL · config.ini</code>, <code>Handler · config.ini</code>를 전환합니다. <code>키 검색</code>으로 키를 필터링하고, 불리언 값은 토글로, 나머지 값은 그 자리에서 편집합니다. 헤더에는 읽어 온 섹션 수와 시각, 로봇에 백업 파일이 있으면 <code>백업 있음</code>이 표시됩니다.</p><p>하단에 저장하지 않은 변경 수(<code>변경 {n}개</code>)가 표시됩니다. <code>되돌리기</code>는 변경을 버리고, <code>다시 읽기</code>는 로봇에서 파일을 다시 읽어오며, <code>저장</code>은 바뀐 키마다 이전 값과 새 값을 나열하는 확인 창 <code>{label}에 저장하시겠습니까?</code>을 엽니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>저장하면 로봇의 파일 <strong>전체</strong>가 에디터의 내용으로 교체됩니다. 항상 방금 읽어 온 파일 위에서 편집하세요. 이전 파일은 <code>*_backup.ini</code>로 남습니다. 변경은 해당 데몬(Motion, HAL, Handler)을 재시작해야 반영되며, 앱이 대신 재시작하지 않습니다. 의미를 모르는 값은 바꾸지 마세요.</p></div><h2 id="팔" tabindex="-1">팔 <a class="header-anchor" href="#팔" aria-label="Permalink to &quot;팔&quot;">​</a></h2><p>로봇이 팔을 보고할 때만 표시됩니다. 이 섹션은 최초 기동용입니다.</p><ol><li><code>CAN 체크</code>, <code>브레이크 해제</code>, <code>제어 시작</code>을 순서대로 누릅니다. 각 단계 후 상태 배지가 켜지는 것을 확인한 뒤 다음을 누르세요. ▶ Auto Start ARM은 이 시퀀스 전체를 한 번에 실행합니다.</li><li><code>정적 자세</code>는 궤적 없이 고정 자세(<code>Straight</code>, <code>Folding</code>, <code>Ready</code>, <code>Lift</code>, <code>Packing</code>, <code>DoorReady</code>)를 보냅니다. 첫 사용은 <code>Ready</code>부터 시작하세요.</li><li><code>관절 잠금 / 조그</code> — 관절 카드를 탭해 잠금/해제하고, 잠긴 관절은 <code>+</code> / <code>−</code>를 길게 눌러 조그합니다(잠금 해제 상태에서는 버튼이 비활성화됩니다).</li></ol><p>RC01 / RC02 부착물 섹션은 이 매뉴얼에서 다루지 않습니다.</p>',29)])])}const V=o(n,[["render",l]]);export{_ as __pageData,V as default};
